 if 'const' in s: assert v==s['const'],(path,'const')
 if 'minLength' in s: assert len(v)>=s['minLength'],(path,'minLength')
 if 'minItems' in s: assert len(v)>=s['minItems'],(path,'minItems')
 if isinstance(v,dict):
  assert set(s.get('required',[]))<=set(v),(path,'missing',set(s.get('required',[]))-set(v))
  if s.get('additionalProperties') is False: assert set(v)<=set(s.get('properties',{})),(path,'additionalProperties')
  for k,sub in s.get('properties',{}).items():
   if k in v: validate(v[k],sub,path+'.'+k)
 if isinstance(v,list) and 'items' in s:
  for i,x in enumerate(v):validate(x,s['items'],f'{path}[{i}]')
validate(p['study'],runtime['study_schema'])
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
